<script>
 import {formatDate} from '$lib/date.js';
 import {onMount,onDestroy} from 'svelte';
 import {page} from '$app/stores';import {locale} from '$lib/i18n.js';
 import {listDeployments} from '$lib/api.js';
 import {notify} from '$lib/stores.js';
 import Button from '$lib/components/Button.svelte';
 let deployments=[],loading=true,refreshing=false,filter='all',search='',refreshTimer,selected=null;
 $: ru=$locale!=='en';
 async function load(silent=false){if(refreshing)return;refreshing=true;const r=await listDeployments($page.url.searchParams.get('project_id')||'');if(r.ok)deployments=r.data.deployments||[];else if(!silent)notify(r.error||'Не удалось загрузить историю деплоев','error');loading=false;refreshing=false;}
 onMount(()=>{load();refreshTimer=setInterval(()=>load(true),15000);});
 onDestroy(()=>{if(refreshTimer)clearInterval(refreshTimer);});
 $: successful=deployments.filter(d=>d.details?.ok===true).length;
 $: failed=deployments.filter(d=>d.details?.ok===false).length;
 $: rollbacks=deployments.filter(d=>d.action==='site_rollback').length;
 $: filtered=deployments.filter(d=>{const ok=d.details?.ok===true;if(filter==='success'&&!ok)return false;if(filter==='failed'&&d.details?.ok!==false)return false;const q=search.trim().toLowerCase();return !q||[d.details?.site_id,d.device,d.action,d.details?.commit_hash,d.details?.error].some(v=>String(v||'').toLowerCase().includes(q));});
 function label(action){return ({site_deploy:ru?'Развёртывание':'Deploy',site_rebuild:ru?'Сборка':'Rebuild',site_rollback:ru?'Откат':'Rollback',site_restart:ru?'Перезапуск':'Restart'})[action]||action;}
 function relative(value){const t=new Date(value).getTime();if(!Number.isFinite(t))return '—';const s=Math.max(0,Math.floor((Date.now()-t)/1000));if(s<60)return 'только что';if(s<3600)return Math.floor(s/60)+' мин. назад';if(s<86400)return Math.floor(s/3600)+' ч. назад';return Math.floor(s/86400)+' дн. назад';}
 function shortCommit(value){return value?String(value).slice(0,12):'';}
</script>
<div class="page-header"><div><div class="eyebrow">DELIVERY / OVERVIEW</div><h1 class="page-title">{ru?'Развёртывания':'Deployments'}</h1><p class="page-desc">{ru?'Мониторинг и управление развёртываниями проектов.':'Monitor and manage your project deployments.'}</p></div><Button on:click={()=>load()} disabled={refreshing}>↻ {ru?'Обновить':'Refresh'}</Button></div>
<div class="stats">
 <article><span >{ru?'Всего операций':'Total operations'}</span><strong>{deployments.length}</strong><small>Последние 100</small></article>
 <article><span >{ru?'Успешно':'Successful'}</span><strong class="good">{successful}</strong><small>Завершены без ошибок</small></article>
 <article><span >{ru?'Ошибки':'Failed'}</span><strong class="bad">{failed}</strong><small>Требуют внимания</small></article>
 <article><span >{ru?'Откаты':'Rollbacks'}</span><strong>{rollbacks}</strong><small>Возврат к прошлому релизу</small></article>
</div>
<div class="toolbar"><div class="filters"><button class:active={filter==='all'} on:click={()=>filter='all'} >{ru?'Все':'All'}</button><button class:active={filter==='success'} on:click={()=>filter='success'} >{ru?'Успешные':'Successful'}</button><button class:active={filter==='failed'} on:click={()=>filter='failed'} >{ru?'С ошибками':'Failed'}</button></div><input class="input search" bind:value={search} placeholder={ru?'Поиск по сайту, устройству или commit…':'Search by site, device or commit…'}/></div>
{#if loading}<div class="empty">Загружаем историю деплоев…</div>{:else if !filtered.length}<div class="empty">{deployments.length?(ru?'По заданным условиям ничего не найдено.':'No deployments match your filters.'):(ru?'Операций пока нет. Запусти Deploy или Rebuild на странице сайта.':'No operations yet. Start Deploy or Rebuild from a site page.')}</div>{:else}
<section class="history">{#each filtered as d (d.id)}<article class="entry"><span class:failed={d.details?.ok===false} class="entry-icon">{d.details?.ok===false?'!':d.action==='site_rollback'?'↶':d.details?.ok===true?'↑':'·'}</span><div class="entry-main"><div class="entry-title"><strong>{label(d.action)}</strong><span class:failed-text={d.details?.ok===false} class="result">{d.details?.ok===true?(ru?'Успешно':'Succeeded'):d.details?.ok===false?(ru?'Ошибка':'Failed'):(ru?'Запись получена':'Recorded')}</span></div><div class="entry-meta"><b>{d.details?.site_id||(ru?'Неизвестный сайт':'Unknown site')}</b><span>{d.device||(ru?'Устройство':'Device')}</span></div>{#if d.details?.commit_hash}<code>{shortCommit(d.details.commit_hash)}</code>{/if}{#if d.details?.error}<p class="error-text">{d.details.error}</p>{/if}</div><time title={formatDate(d.created_at)}>{relative(d.created_at)}<small>{formatDate(d.created_at)}</small></time><button class="details-button" on:click={()=>selected=d}>{ru?'Детали':'Details'}</button></article>{/each}</section>
{/if}
<p class="footnote">{ru?'Автообновление каждые 15 секунд. Страница показывает подтверждённые записи операций. Активные build jobs и отмена задач пока не предоставляются API.':'Auto-refreshes every 15 seconds. This page shows confirmed operation records. Live build jobs and cancellation are not exposed by the API yet.'}</p>
{#if selected}<div class="details-backdrop" on:click={()=>selected=null}><section class="details-panel" on:click|stopPropagation><div class="details-head"><h2>{ru?'Детали операции':'Deployment details'}</h2><button on:click={()=>selected=null}>×</button></div><div class="detail-row"><span>ID</span><strong>{selected.id}</strong></div><div class="detail-row"><span>{ru?'Проект / сайт':'Project / site'}</span><strong>{selected.details?.project_id||selected.details?.site_id||'—'}</strong></div><div class="detail-row"><span>{ru?'Версия / commit':'Version / commit'}</span><strong>{selected.details?.commit_hash||'—'}</strong></div><div class="detail-row"><span>{ru?'Устройство':'Device'}</span><strong>{selected.device||'—'}</strong></div><div class="detail-row"><span>{ru?'Время':'Time'}</span><strong>{selected.created_at?formatDate(selected.created_at):'—'}</strong></div><div class="detail-row"><span>{ru?'Статус':'Status'}</span><strong>{selected.details?.ok===true?(ru?'Успешно':'Succeeded'):selected.details?.ok===false?(ru?'Ошибка':'Failed'):(ru?'Запись получена':'Recorded')}</strong></div>{#if selected.details?.error}<pre class="detail-error">{selected.details.error}</pre>{/if}<p class="logs-unavailable">{ru?'Build logs не входят в запись этой операции. Открой страницу сайта на устройстве для доступных логов.':'Build logs are not included in this operation record. Open the site on its device for available logs.'}</p></section></div>{/if}
<style>
.details-button{border:1px solid var(--border);border-radius:6px;padding:5px 8px;background:transparent;color:var(--text-muted);font-size:9px}.details-backdrop{position:fixed;inset:0;z-index:70;display:flex;justify-content:flex-end;background:#0009}.details-panel{width:min(440px,100%);height:100%;overflow:auto;padding:18px;background:var(--bg-card);border-left:1px solid var(--border)}.details-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.details-head h2{font-size:14px}.details-head button{border:0;background:transparent;color:var(--text-main);font-size:20px}.detail-row{display:flex;justify-content:space-between;gap:15px;padding:11px 0;border-bottom:1px solid var(--border);font-size:10px}.detail-row span{color:var(--text-muted)}.detail-row strong{text-align:right;overflow-wrap:anywhere}.detail-error{margin-top:14px;padding:10px;border:1px solid #EF646455;border-radius:7px;color:#EF6464;white-space:pre-wrap}.logs-unavailable{margin-top:15px;color:var(--text-muted);font-size:10px;line-height:1.6}.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--text-muted);font-weight:700;margin-bottom:7px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:18px}.stats article{display:grid;gap:7px;padding:15px;border:1px solid var(--border);border-radius:8px;background:var(--bg-card)}.stats span,.stats small{font-size:10px;color:var(--text-muted)}.stats strong{font-size:25px;font-weight:650;letter-spacing:-.04em}.stats strong.good{color:var(--success)}.stats strong.bad{color:var(--danger)}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 12px}.filters{display:flex;gap:4px;padding:3px;border:1px solid var(--border);border-radius:7px;background:var(--bg-base)}.filters button{border:0;background:transparent;color:var(--text-muted);padding:6px 10px;border-radius:5px;font-size:10px}.filters button.active{background:var(--border);color:var(--text-main)}.search{max-width:330px}.history{border:1px solid var(--border);border-radius:8px;background:var(--bg-card);overflow:hidden}.entry{display:flex;align-items:flex-start;gap:12px;padding:14px;border-bottom:1px solid var(--border)}.entry:last-child{border:0}.entry-icon{width:30px;height:30px;display:grid;place-items:center;flex:none;border-radius:7px;background:var(--accent-soft);color:var(--success);font-weight:700}.entry-icon.failed{background:var(--bg-elevated);color:var(--danger)}.entry-main{flex:1;min-width:0;display:grid;gap:5px}.entry-title{display:flex;align-items:center;gap:8px}.entry-title strong{font-size:12px;font-weight:600}.result{font-size:9px;color:var(--success)}.result.failed-text{color:var(--danger)}.entry-meta{display:flex;flex-wrap:wrap;gap:9px;color:var(--text-muted);font-size:10px}.entry-meta b{color:var(--text-main);font-weight:550}.entry code{font:10px var(--mono,monospace);color:var(--text-muted)}.error-text{font-size:10px;color:var(--danger);overflow-wrap:anywhere}.entry time{display:grid;gap:3px;text-align:right;white-space:nowrap;font-size:10px;color:var(--text-main)}.entry time small{font-size:9px;color:var(--text-dim)}.footnote{margin-top:12px;color:var(--text-dim);font-size:10px}@media(max-width:760px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar{align-items:stretch;flex-direction:column}.search{max-width:none}.entry time{white-space:normal;max-width:100px}}
</style>